#!/bin/sh
# Runstory installer. curl -fsSL https://runstory.specstory.com/install.sh | sh
# Adapted from the verified hosted SpecStory installer, SHA-256
# 3251428c67241e8da01599b34b6f1ce9bc4653afba53c9007d577976aafed4cc.
# Generated by release/render-installer.mjs from the shared CLI contract.
main() (
  set -eu
  umask 077
  fail() { printf 'Runstory: %s\n' "$*" >&2; exit 1; }
  # A Windows bash shell, e.g. Git Bash, MSYS2 or Cygwin, gets the Windows build
  # from install.ps1, which Windows PowerShell runs (Phase 389). This comes
  # before the tool check, which such a shell may fail. Standard input is
  # /dev/null, so the child never reads the rest of a piped script, and this
  # script exits with the child's code. RUNSTORY_VERSION, RUNSTORY_INSTALL_DIR
  # and RUNSTORY_NO_MODIFY_PATH reach the child through the environment.
  case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*)
      windows_powershell="${SYSTEMROOT:-${SystemRoot:-C:/Windows}}/System32/WindowsPowerShell/v1.0/powershell.exe"
      # With no Windows PowerShell nothing is installed, and the person gets the
      # Windows line that every page shows, to run in PowerShell (Phase 405).
      [ -f "$windows_powershell" ] || { printf 'Runstory: Windows PowerShell was not found at %s. Nothing was installed. Run this line in PowerShell instead.\n  %s\n' "$windows_powershell" 'powershell -ExecutionPolicy Bypass -c "irm https://runstory.specstory.com/install.ps1 | iex"' >&2; exit 1; }
      printf 'Runstory: This is a Windows shell, so the Windows installer runs the install.\n'
      handoff_status=0
      "$windows_powershell" -NoProfile -ExecutionPolicy Bypass -Command "irm https://runstory.specstory.com/install.ps1 | iex" < /dev/null || handoff_status=$?
      exit "$handoff_status" ;;
  esac
  for dependency in curl openssl tar gzip mktemp awk grep sed chmod mv mkdir cat rm uname wc id stat tr tail head od sleep; do
    command -v "$dependency" >/dev/null 2>&1 || fail "Install $dependency, then try again."
  done
  releases='https://runstory.specstory.com/api/cli/releases'
  storage='https://actgnmsszoegjfmjwvry.supabase.co/storage/v1/object/public/cli-releases'
  # The mawk of Ubuntu 22.04 and Debian 12 reads no bound such as {0,8}, so the
  # version is matched with grep -E, as 1 line.
  valid_version() { [ "$(printf '%s\n' "$1" | wc -l | tr -d ' ')" = 1 ] && printf '%s\n' "$1" | grep -Eq '^(0|[1-9][0-9]{0,8})\.(0|[1-9][0-9]{0,8})\.(0|[1-9][0-9]{0,8})$'; }
  checksum() { openssl dgst -sha256 "$1" | sed 's/^.*= //'; }
  bytes() { wc -c < "$1" | tr -d ' '; }
  owner() { if [ "$(uname -s)" = Darwin ]; then stat -f '%u' "$1"; else stat -c '%u' "$1"; fi; }
  case "$(uname -s)" in Darwin) platform=darwin ;; Linux) platform=linux ;; *) fail 'Supported systems are macOS and Linux.' ;; esac
  case "$(uname -m)" in x86_64|amd64) arch=amd64 ;; arm64|aarch64) arch=arm64 ;; *) fail 'Supported processors are amd64 and arm64.' ;; esac
  install_dir=${RUNSTORY_INSTALL_DIR:-${HOME:?HOME must be set}/.local/bin}
  case "$install_dir" in /*) ;; *) fail 'RUNSTORY_INSTALL_DIR must be absolute.' ;; esac
  case "$install_dir" in *'
'*|*''*) fail 'The install path cannot contain a newline.' ;; esac
  mkdir -p "$install_dir" || fail 'Choose a writable RUNSTORY_INSTALL_DIR.'
  install_dir=$(cd "$install_dir" && pwd -P)
  case "$install_dir/" in */node_modules/*|*/Cellar/*|*/Caskroom/*|/nix/store/*|/usr/bin/*|/bin/*|/snap/*) fail 'This directory is managed by another installer. Use its update command or choose RUNSTORY_INSTALL_DIR.' ;; esac
  [ "$(owner "$install_dir")" = "$(id -u)" ] && [ -w "$install_dir" ] || fail 'The install directory must be owned and writable by you. No sudo is used.'
  target="$install_dir/runstory"
  receipt="$install_dir/.runstory-install"
  safe_target() {
    [ ! -L "$target" ] && [ ! -d "$target" ] || fail "Refusing a symlink or directory at $target. Use your package manager to update."
    if [ -e "$target" ]; then [ -f "$target" ] && [ -w "$target" ] && [ "$(owner "$target")" = "$(id -u)" ] || fail 'The existing binary must be a regular file owned and writable by you.'; fi
    [ ! -L "$receipt" ] && [ ! -d "$receipt" ] || fail 'Refusing an unsafe install receipt.'
  }
  safe_target
  before=absent
  if [ -e "$target" ]; then before=$(checksum "$target"); fi
  download_dir=$(mktemp -d "${TMPDIR:-/tmp}/runstory-install.XXXXXXXX") || fail 'Could not create temporary storage.'
  active_pid=''
  cleanup() {
    if [ -n "$active_pid" ]; then kill -KILL "$active_pid" 2>/dev/null || :; wait "$active_pid" 2>/dev/null || :; fi
    rm -rf "$download_dir"
  }
  trap cleanup EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  trap 'exit 129' HUP
  bounded() {
    bound_seconds=$1; shift
    "$@" &
    active_pid=$!; bound_ticks=0
    while kill -0 "$active_pid" 2>/dev/null; do
      [ "$bound_ticks" -lt "$((bound_seconds * 10))" ] || fail "Packaged executable or archive command exceeded $bound_seconds seconds."
      sleep 0.1; bound_ticks=$((bound_ticks + 1))
    done
    if wait "$active_pid"; then bound_status=0; else bound_status=$?; fi
    active_pid=''
    return "$bound_status"
  }
  cat > "$download_dir/key.pem" <<'CLI_RELEASE_KEY'
-----BEGIN PUBLIC KEY-----
MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEbv6sY0W8/yYrF7RnAfSta3LHTY2q
8K7pPn70/RZNmFnPmBNqav1p5EPUdhe/tTVdcKTjaQVsdin7K6Z3wRnpWQ==
-----END PUBLIC KEY-----
CLI_RELEASE_KEY
  openssl pkey -pubin -in "$download_dir/key.pem" -noout >/dev/null 2>&1 || fail 'Release signing is not configured yet. No binary was replaced.'
  # Every download is counted as it arrives. curl before 8.4.0, e.g. the curl of
  # Ubuntu 22.04 and Debian 12, applies --max-filesize only to a response that
  # declares its length, so curl writes to head, which keeps at most 1 byte more
  # than the bound. curl's exit is kept in a file, and the HTTP code is read from
  # the headers curl dumped. get sets code, or stops with its 4th argument.
  get() {
    rm -f "$download_dir/headers" "$download_dir/status"
    { curl_status=0; curl --silent --show-error --proto '=https' --tlsv1.2 --connect-timeout 15 --max-time 300 --max-filesize "$3" --max-redirs 0 --dump-header "$download_dir/headers" --output - "$1" 2> "$download_dir/errors" || curl_status=$?; printf '%s\n' "$curl_status" > "$download_dir/status"; } | head -c "$(($3 + 1))" > "$2" || fail "$4"
    [ "$(bytes "$2")" -le "$3" ] || fail 'A release download exceeded its size limit.'
    curl_status=$(cat "$download_dir/status")
    [ "$curl_status" != 63 ] || fail 'A release download exceeded its size limit.'
    [ "$curl_status" = 0 ] || { cat "$download_dir/errors" >&2; fail "$4"; }
    code=$(tr -d '\r' < "$download_dir/headers" | awk '/^HTTP\// {code=$2} END {print code}')
  }
  # Never follow an arbitrary redirect. A friendly artifact route can redirect
  # once, only to the exact public object at the pinned storage origin.
  fetch() {
    url=$1; output=$2; limit=$3; expected_redirect=${4:-}
    get "$url" "$output" "$limit" 'Download failed. The existing installation was not replaced.'
    case "$code" in
      200) ;;
      302|307|308)
        location=$(sed -n 's/^[Ll][Oo][Cc][Aa][Tt][Ii][Oo][Nn]:[[:space:]]*//p' "$download_dir/headers" | tr -d '\r')
        [ -n "$expected_redirect" ] && [ "$location" = "$expected_redirect" ] || fail 'The release redirected to an unexpected location.'
        get "$location" "$output" "$limit" 'Artifact download failed.'
        [ "$code" = 200 ] || fail 'Artifact storage did not return the requested file.' ;;
      *) fail "Release download returned HTTP $code." ;;
    esac
    [ "$(bytes "$output")" -le "$limit" ] || fail 'A release download exceeded its size limit.'
  }
  version=${RUNSTORY_VERSION:-}
  if [ -z "$version" ]; then
    fetch "$releases/latest.txt" "$download_dir/latest" 32
    [ "$(tail -c 1 "$download_dir/latest" | od -An -tu1 | tr -d ' ')" = 10 ] || fail 'The release pointer is malformed.'
    version=$(cat "$download_dir/latest")
    [ "$(bytes "$download_dir/latest")" -eq $((${#version}+1)) ] || fail 'The release pointer is malformed.'
  fi
  valid_version "$version" || fail 'Expected a stable version such as 1.2.3.'
  archive="runstory_${version}_${platform}_${arch}.tar.gz"
  checksums="runstory_${version}_checksums.txt"
  manifest="runstory_${version}_release.json"
  base="$releases/v$version"; object="$storage/v$version"
  printf 'Runstory %s\n  1/3 Downloading and checking the signature for %s/%s...\n' "$version" "$platform" "$arch"
  fetch "$base/$checksums" "$download_dir/checksums" 4096 "$object/$checksums"
  fetch "$base/$checksums.sig" "$download_dir/signature" 128 "$object/$checksums.sig"
  openssl dgst -sha256 -verify "$download_dir/key.pem" -signature "$download_dir/signature" "$download_dir/checksums" >/dev/null 2>&1 || fail 'Release signature verification failed. Nothing was installed.'
  [ "$(tail -c 1 "$download_dir/checksums" | od -An -tu1 | tr -d ' ')" = 10 ] || fail 'Checksums must end with LF.'
  # The signed set is exactly four platform archives and one manifest.
  awk -v v="$version" '
    BEGIN { split("darwin_amd64 darwin_arm64 linux_amd64 linux_arm64", p); for(i in p) wanted["runstory_"v"_"p[i]".tar.gz"]=1; wanted["runstory_"v"_release.json"]=1 }
    { if(length($1)!=64 || $1 ~ /[^0-9a-f]/ || $0!=$1"  "$2 || !wanted[$2] || seen[$2]++) bad=1 }
    END { if(NR!=5) bad=1; exit bad }
  ' "$download_dir/checksums" || fail 'The signed checksum set is malformed or incomplete.'
  fetch "$base/$archive" "$download_dir/archive" 104857600 "$object/$archive"
  fetch "$base/$manifest" "$download_dir/manifest" 4096 "$object/$manifest"
  for pair in "$archive:archive" "$manifest:manifest"; do
    name=${pair%:*}; local_name=${pair#*:}
    expected=$(awk -v name="$name" '$2==name {print $1}' "$download_dir/checksums")
    [ "$expected" = "$(checksum "$download_dir/$local_name")" ] || fail 'A release file failed its SHA-256 check.'
  done
  printf '  2/3 Checking the packaged executable...\n'
  # ulimit is a second decompression bound even on older curl/tar versions.
  bounded 15 sh -c 'ulimit -f "$1"; exec gzip -dc "$2"' sh 262144 "$download_dir/archive" > "$download_dir/archive.tar" || fail 'Malformed or oversized compressed archive.'
  [ "$(bytes "$download_dir/archive.tar")" -le 268435456 ] || fail 'The expanded archive is too large.'
  bounded 15 tar -tf "$download_dir/archive.tar" > "$download_dir/members" || fail 'Malformed tar archive.'
  awk '$0 !~ /^[A-Za-z0-9_.-]+$/ || $0=="." || $0==".." || seen[$0]++ {bad=1} $0=="runstory" {n++} END {exit bad || n!=1}' "$download_dir/members" || fail 'Unsafe or duplicate archive member.'
  bounded 15 tar -tvf "$download_dir/archive.tar" > "$download_dir/types" || fail 'Cannot inspect archive members.'
  awk 'substr($0,1,1)!="-" {bad=1} END {exit bad}' "$download_dir/types" || fail 'Archive links and special files are refused.'
  # A root shell's tar keeps the archive's owner, e.g. uid 1001 with GNU tar, and
  # the native bootstrap refuses a file another user owns. --no-same-owner gives
  # the file to the installing user, as tar already does for a user who is not root.
  bounded 15 tar --no-same-owner -xf "$download_dir/archive.tar" -C "$download_dir" runstory || fail 'Could not extract runstory.'
  [ -f "$download_dir/runstory" ] && [ ! -L "$download_dir/runstory" ] && [ "$(bytes "$download_dir/runstory")" -le 104857600 ] || fail 'Invalid packaged binary.'
  chmod 755 "$download_dir/runstory"
  binary_hash=$(checksum "$download_dir/runstory")
  safe_target
  now=absent
  if [ -e "$target" ]; then now=$(checksum "$target"); fi
  [ "$now" = "$before" ] || fail 'The installation changed during download. Run the installer again.'
  # The native bootstrap verifies its own --version with the updater's bounded
  # child handling before it acquires the install lock or changes the target.
  printf '  3/3 Installing...\n'
  RUNSTORY_NO_UPDATE_CHECK=1 "$download_dir/runstory" __install --dir "$install_dir" --version "$version" --sha256 "$binary_hash" || fail 'Native installation failed. Follow its recovery instructions above.'
  [ -f "$target" ] && [ ! -L "$target" ] && [ "$(checksum "$target")" = "$binary_hash" ] || fail 'The installed binary did not match the verified candidate.'
  printf '\nInstalled and verified: %s\nLocation: %s\n' "$version" "$target"
  printf '%s' "$PATH" | awk -v RS=: 'NF {print}' | while IFS= read -r directory; do
    candidate="$directory/runstory"
    if [ -x "$candidate" ] && [ "$candidate" != "$target" ]; then printf 'Other installation left in place: %s\n' "$candidate"; fi
  done
  quoted_dir=$(printf '%s' "$install_dir" | sed "s/'/'\\\\''/g")
  printf '\nAdd it to your PATH in this terminal:\n'
  case "${SHELL:-}" in
    */fish) printf '  fish_add_path --move '\''%s'\''\n' "$quoted_dir" ;;
    *) printf '  export PATH='\''%s'\'':"$PATH"\n' "$quoted_dir"; case "${SHELL:-}" in */zsh) printf '  rehash\n' ;; *) printf '  hash -r\n' ;; esac ;;
  esac
  printf '\nThen set up your project:\n  runstory init\n  runstory setup\n'
)
# Keep this call last. A truncated script cannot run a partial installer.
main "$@"
